import re,os
hits=[]
for root,dirs,files in os.walk('AlgebraicJacobian'):
    for f in files:
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f)
        lines=open(p,encoding='utf-8').read().split('\n')
        for i,l in enumerate(lines):
            if re.match(r'\s*(noncomputable\s+)?(scoped\s+)?instance\b', l):
                # look forward until next decl start
                body=[]
                j=i
                while j<len(lines) and j<i+40:
                    if j>i and re.match(r'\s*(@\[|/--|noncomputable |theorem |lemma |def |instance |class |structure |abbrev |end |namespace |section )', lines[j]):
                        break
                    body.append(lines[j]); j+=1
                bt='\n'.join(body)
                if re.search(r'(?<![A-Za-z])sorry(?![A-Za-z])', bt):
                    hits.append((p,i+1,l.strip()))
for h in hits: print(h)
EOF
